        // seq(1, upb).TakeWhile(i => countLength(0, i - 1) <= countLength(i, upb))
        // countLength(left, right) = right - left + 1 if left <= right else 0
        // countLength(0, i - 1) = i (if i >= 1)
        // countLength(i, upb) = upb - i + 1 = n - i

        // Condition: i <= n - i  =>  2*i <= n

        for (long long i = 1; i <= upb; ++i) {
            long long lenLeft = i; // countLength(0, i-1)
            long long lenRight = n - i; // countLength(i, upb)

